import React from "react";
import {
  FormStep,
  Input,
  FormItem,
  FormButtonGroup,
} from "@storage-fe/formily-arco";
import { createForm } from "@formily/core";
import { FormProvider, createSchemaField, FormConsumer } from "@formily/react";
import { Button } from "@arco-design/web-react";
import { autorun } from "@formily/reactive";

const SchemaField = createSchemaField({
  components: {
    FormItem,
    FormStep,
    Input,
  },
});

const form = createForm();
const formStep = FormStep.createFormStep();

export default () => (
  <FormProvider form={form}>
    <SchemaField>
      <SchemaField.Void
        x-component="FormStep"
        x-component-props={{
          formStep: formStep,
          mode: "Schema",
        }}
      >
        <SchemaField.Void
          x-component="FormStep.StepPane"
          x-component-props={{ title: "第一步", name: "first" }}
        >
          <SchemaField.String
            name="aaa"
            x-decorator="FormItem"
            required
            x-component="Input"
          />
        </SchemaField.Void>
        <SchemaField.Void
          x-component="FormStep.StepPane"
          x-component-props={{ title: "第二步", name: "second" }}
        >
          <SchemaField.String
            name="bbb"
            x-decorator="FormItem"
            required
            x-component="Input"
          />
        </SchemaField.Void>
        <SchemaField.Void
          type="void"
          x-component="FormStep.StepPane"
          x-component-props={{ title: "第三步", name: "third" }}
        >
          <SchemaField.String
            name="ccc"
            x-decorator="FormItem"
            required
            x-component="Input"
          />
        </SchemaField.Void>
      </SchemaField.Void>
    </SchemaField>
    <FormConsumer>
      {() => (
        <FormButtonGroup>
          <Button
            disabled={!formStep.allowBack}
            onClick={() => {
              formStep.back();
            }}
          >
            上一步
          </Button>
          <Button
            disabled={!formStep.allowNext}
            onClick={() => {
              formStep.next();
            }}
          >
            下一步
          </Button>
          <Button
            disabled={formStep.allowNext}
            onClick={() => {
              formStep.submit((values: any) => {
                console.log(values);
                return Promise.resolve({} as any);
              });
            }}
          >
            提交
          </Button>
        </FormButtonGroup>
      )}
    </FormConsumer>
  </FormProvider>
);

autorun(() => {
  console.log("next", formStep.allowNext, new Date());
});

// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore
window.formStep = formStep;
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
